#include <stdio.h>

int main() {
    int K;
    scanf("%d", &K);
    int a[K];
    long long total = 0;
    for (int i = 0; i < K; i++) {
        scanf("%d", &a[i]);
        total += a[i];
    }

    int base[K];
    int used[K+1];
    for (int i = 0; i < K; i++) used[i+1] = 0;

    long long n = total;
    long long base_count = n / K;  // each of first K positions appears this many times in whole seq
    long long extra = n % K;       // first 'extra' positions appear one more time

    int possible = 1;
    for (int i = 0; i < K; i++) {
        int need = base_count + (i < extra ? 1 : 0);
        // find smallest number j not used yet with a[j-1] == need
        int found = 0;
        for (int j = 1; j <= K; j++) {
            if (!used[j] && a[j-1] == need) {
                base[i] = j;
                used[j] = 1;
                found = 1;
                break;
            }
        }
        if (!found) {
            possible = 0;
            break;
        }
    }

    if (!possible) {
        printf("-1\n");
        return 0;
    }

    // Construct full sequence
    long long printed = 0;
    for (long long pos = 0; pos < n; pos++) {
        if (printed) printf(" ");
        printf("%d", base[pos % K]);
        printed++;
    }
    printf("\n");

    return 0;
}

