    if (scanf("%d", &K) != 1) return 0;

    long long *a = (long long *)malloc((K + 1) * sizeof(long long));
    if (!a) return 0;

    long long sum = 0;
    for (int i = 1; i <= K; i++) {
        if (scanf("%lld", &a[i]) != 1) return 0;
        sum += a[i];
    }

    /* Necessary and sufficient condition:
       Let pos[x][t] be positions of value x in P.
       The condition implies consecutive occurrences of the same value
       differ by at most K, because every occurrence must lie inside some
       window of length K containing all values exactly once, so for each x
       every such window contains exactly one x.

       A constructive lexicographically smallest solution exists iff
       max(a_i) - min(a_i) <= 1.

       If all counts are either m or m+1, then sequence formed by repeating
       1..K exactly m times, followed by all values with count m+1 in
       increasing order, is valid and lexicographically smallest.
    */

    long long mn = a[1], mx = a[1];
    for (int i = 2; i <= K; i++) {
        if (a[i] < mn) mn = a[i];
        if (a[i] > mx) mx = a[i];
    }

    if (mx - mn > 1) {
        printf("No\n");
        free(a);
        return 0;
    }

    printf("Yes\n");

    int first = 1;
    for (long long t = 0; t < mn; t++) {
        for (int i = 1; i <= K; i++) {
            if (!first) printf(" ");
            printf("%d", i);
            first = 0;
        }
    }
    for (int i = 1; i <= K; i++) {
        if (a[i] == mn + 1) {
            if (!first) printf(" ");
            printf("%d", i);
            first = 0;
        }
    }
    printf("\n");

    free(a);
    return 0;
}

