int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int K;
    cin >> K;
    vector<int> a(K);
    long long total = 0;
    for (int i = 0; i < K; i++) {
        cin >> a[i];
        total += a[i];
    }

    if (total < K) {
        cout << -1 << "\n";
        return 0;
    }

    long long q = total / K;
    long long r = total % K;

    vector<int> more, less;
    for (int i = 0; i < K; i++) {
        if (a[i] == q + 1) more.push_back(i + 1);
        else if (a[i] == q) less.push_back(i + 1);
        else {
            cout << -1 << "\n";
            return 0;
        }
    }

    if ((int)more.size() != r || (int)less.size() != K - r) {
        cout << -1 << "\n";
        return 0;
    }

    vector<int> perm;
    // first r positions: numbers that appear q+1 times, in increasing order
    sort(more.begin(), more.end());
    sort(less.begin(), less.end());
    for (int x : more) perm.push_back(x);
    for (int x : less) perm.push_back(x);

    for (int i = 0; i < total; i++) {
        if (i) cout << " ";
        cout << perm[i % K];
    }
    cout << "\n";

    return 0;
}

