int main(){
    int K;
    cin >> K;
    vector<int> a(K+1);
    long long N = 0;
    for(int i = 1; i <= K; i++){ cin >> a[i]; N += a[i]; }

    // c[r] = floor((N-r-1)/K)+1 for r=0..K-1
    // group values by their required count, assign smallest value to earliest position greedily
    // For each position r, c_r is determined. Assign smallest available value with a[v]=c_r

    map<long long, set<int>> byCount;
    for(int v = 1; v <= K; v++) byCount[a[v]].insert(v);

    vector<int> P_base(K);
    for(int r = 0; r < K; r++){
        long long cr = (N - r - 1)/K + 1;
        auto it = byCount.find(cr);
        if(it == byCount.end() || it->second.empty()){ cout << -1; return 0; }
        int v = *it->second.begin();
        it->second.erase(it->second.begin());
        P_base[r] = v;
    }
    for(long long i = 0; i < N; i++){
        cout << P_base[i % K];
        if(i < N-1) cout << ' ';
    }
    cout << endl;
