int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int K;
    cin >> K;
    vector<long long> a(K + 1);
    long long sum = 0;
    for (int i = 1; i <= K; ++i) {
        cin >> a[i];
        sum += a[i];
    }

    // Necessary and sufficient condition:
    // Let positions of value x be p1 < p2 < ... < p_ax.
    // Since every occurrence must belong to some length-K window that is a permutation,
    // adjacent equal values must be at least K apart.
    // Thus ax occurrences of x require length at least (ax-1)K + 1, so overall
    // sum >= (max(a)-1)K + 1  <=> max(a) <= ceil(sum / K).
    //
    // It is also sufficient: construct by distributing values into blocks cyclically.
    long long mx = 0;
    for (int i = 1; i <= K; ++i) mx = max(mx, a[i]);

    if (mx > (sum + K - 1) / K) {
        cout << -1 << '\n';
        return 0;
    }

    // Lexicographically smallest valid sequence:
    // Repeatedly take one copy of each currently remaining value in increasing order.
    // This forms layers; any full K consecutive positions across layers become a permutation,
    // and every occurrence belongs to such a window.
    //
    // More concretely, if cnt[i] remain, for t = 1..mx:
    // output all i with cnt[i] >= mx-t+1, in increasing order.
    // Equivalent simpler implementation:
    // for level = 1..mx, output all i with a[i] >= level.
    vector<int> ans;
    ans.reserve((size_t)sum);

    for (long long level = 1; level <= mx; ++level) {
        for (int i = 1; i <= K; ++i) {
            if (a[i] >= level) ans.push_back(i);
        }
    }

    // Output
    for (int i = 0; i < (int)ans.size(); ++i) {
        if (i) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';
    return 0;
}

