        List<Integer> result = new ArrayList<>();

        // For the first K positions, we need a permutation
        // We'll try to make it lexicographically smallest
        int minCount = Integer.MAX_VALUE;
        for (int i = 1; i <= K; i++) {
            minCount = Math.min(minCount, a[i]);
        }

        // The sequence will consist of minCount full permutations
        // plus possibly some extra elements

        // We'll build greedily
        // At each position, try smallest possible number that can work

        int[] remaining = new int[K + 1];
        System.arraycopy(a, 1, remaining, 1, K);

        // For the first K positions, we must place a permutation
        // We need to ensure we can complete the rest

        // Use a deque to maintain current window
        Deque<Integer> window = new ArrayDeque<>();
        int[] windowCount = new int[K + 1];

        // Build first K elements - lexicographically smallest possible permutation
        boolean[] used = new boolean[K + 1];
        for (int pos = 0; pos < K; pos++) {
            for (int num = 1; num <= K; num++) {
                if (!used[num] && remaining[num] > 0) {
                    // Check if placing this number can lead to a valid solution
                    used[num] = true;
                    remaining[num]--;
                    window.addLast(num);
                    windowCount[num]++;

                    if (pos == K - 1 || canComplete(result.size() + 1, remaining, window, windowCount, K, totalLength)) {
                        result.add(num);
                        break;
                    } else {
                        // Backtrack
                        used[num] = false;
                        remaining[num]++;
                        window.removeLast();
                        windowCount[num]--;
                    }
                }
            }
        }

        // Now continue building the rest
        while (result.size() < totalLength) {
            int leaving = window.removeFirst();
            windowCount[leaving]--;

            boolean placed = false;
            for (int num = 1; num <= K; num++) {
                if (remaining[num] > 0 && num != leaving) {
                    // Check if valid
                    remaining[num]--;
                    window.addLast(num);
                    windowCount[num]++;

                    if (canComplete(result.size() + 1, remaining, window, windowCount, K, totalLength)) {
                        result.add(num);
                        placed = true;
                        break;
                    } else {
                        remaining[num]++;
                        window.removeLast();
                        windowCount[num]--;
                    }
                }
            }

            if (!placed) {
                System.out.println(-1);
                return;
            }
        }

        // Output result
