public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int K;
        try {
            K = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        long[] a = new long[K + 1];
        long sum = 0;
        long min = Long.MAX_VALUE;
        for (int i = 1; i <= K; i++) {
            a[i] = fs.nextLong();
            sum += a[i];
            min = Math.min(min, a[i]);
        }

        // Necessary and sufficient condition:
        // all counts differ by at most 1.
        long max = Long.MIN_VALUE;
        for (int i = 1; i <= K; i++) max = Math.max(max, a[i]);
        if (max - min > 1) {
            System.out.println(-1);
            return;
        }

        // Let m = min count. Then sequence consists of:
        // [1..K] repeated m times, plus one extra occurrence of elements with count m+1.
        // To be lexicographically smallest, place extra elements as late as possible,
        // while keeping them in increasing order within one permutation block.
        //
        // If S = {i | a[i] = m+1}, then answer:
        // [1..K] repeated m times, then elements of S in increasing order.
        //
        // This works because every position belongs to some length-K window that is a permutation.

        StringBuilder sb = new StringBuilder();

        for (long t = 0; t < min; t++) {
            for (int i = 1; i <= K; i++) {
                sb.append(i).append(' ');
            }
        }
        for (int i = 1; i <= K; i++) {
            if (a[i] == min + 1) sb.append(i).append(' ');
        }

        if (sb.length() > 0) sb.setLength(sb.length() - 1);
        System.out.println(sb.toString());
    }
}

