        // build sequence greedily
        int[] P = new int[N+1];
        int[] rem = Arrays.copyOf(a, K+1);
        boolean[] inWindow = new boolean[K+1];
        // fill first window - must be permutation, lex smallest
        // first window: assign 1..K in some order - but must be lex smallest permutation of 1..K
        // Actually first K elements form a permutation - lex smallest is 1,2,...,K if all a[i]>=1
        for(int i=1;i<=K;i++){if(rem[i]<1){System.out.println(-1);return;}inWindow[i]=true;}
        for(int i=1;i<=K;i++){P[i]=i;rem[i]--;}
        // now slide
        for(int i=K+1;i<=N;i++){
            int leaving=P[i-K];inWindow[leaving]=false;
            // choose smallest not in window with rem>0, feasible
            int chosen=-1;
            for(int v=1;v<=K;v++){
                if(!inWindow[v]&&rem[v]>0){
                    // feasibility: after choosing v, check each remaining count <= future available slots
                    // future positions: i+1..N, count = N-i
